"""G016 stage 0: attribute the test node's disk reads to LMDB tables, per 1,000-block window.
usage: python3 -I analyze.py <run dir> [<window blocks, default 1000>]
Reads <run dir>/run.log (node pid, mono0), bio.txt (bpftrace: ns pid rwbs sector nr_sector), fiemap.txt (filefrag -v of
data.mdb after the run), map_start.txt / map_end.txt (pagemap runs) and samples.csv (sampler.py).
A read page is labelled by the start map, unless the start map has it free, unlabelled or beyond its end: then by the end
map, prefixed "new:" (a page written during the run and read back after it left the cache)."""
import bisect, csv, re, sys
from collections import Counter, defaultdict

run = sys.argv[1]
W = int(sys.argv[2]) if len(sys.argv) > 2 else 1000
START = 3106400
log = open(run + "/run.log").read()
pid = int(re.search(r"test node pid (\d+)", log).group(1))
mono0 = int(re.search(r"mono0 (\d+)", log).group(1))

def load_map(path):
    firsts, lasts, labels = [], [], []
    for line in open(path):
        a, b, lab = line.split()
        firsts.append(int(a)); lasts.append(int(b)); labels.append(lab)
    return firsts, lasts, labels

def lookup(m, page):
    firsts, lasts, labels = m
    i = bisect.bisect_right(firsts, page) - 1
    if i < 0 or page > lasts[i]:
        return None
    return labels[i]

mstart, mend = load_map(run + "/map_start.txt"), load_map(run + "/map_end.txt")

# FIEMAP: filefrag -v lines "  n:  lstart..  lend:  pstart..  pend:  len: ..." in 4 KiB blocks
ext = []
for line in open(run + "/fiemap.txt"):
    m = re.match(r"\s*\d+:\s+(\d+)\.\.\s*(\d+):\s+(\d+)\.\.\s*(\d+):", line)
    if m:
        ls, le, ps, pe = map(int, m.groups())
        ext.append((ps, pe, ls))
ext.sort()
pstarts = [e[0] for e in ext]

def page_of_sector(sector):
    blk = sector // 8
    i = bisect.bisect_right(pstarts, blk) - 1
    if i < 0:
        return None
    ps, pe, ls = ext[i]
    if blk > pe:
        return None
    return ls + (blk - ps)

# heights over time
samples = list(csv.DictReader(open(run + "/samples.csv")))
times = [int(s["mono_ns"]) for s in samples if s["height"]]
heights = [int(s["height"]) for s in samples if s["height"]]
cpu = [(int(s["mono_ns"]), int(s["height"]) if s["height"] else None, int(s["cpu_ticks"]), int(s["blkio_ticks"])) for s in samples]

def window_at(ns):
    i = bisect.bisect_right(times, ns) - 1
    if i < 0:
        return -1  # before the first sample: startup
    top = heights[i] - 1
    return max(-1, (top - START) // W) if top > START else -1

def label_page(page):
    lab = lookup(mstart, page)
    if lab is None or lab in ("@free", "@none"):
        e = lookup(mend, page)
        return "new:" + (e or "?")
    return lab

# the warm-up thread: the node's tid with the most reads between the warm-up's start and end lines (node.log, UTC)
import calendar, datetime
def log_unix(line):
    d = datetime.datetime.strptime(line[:23], "%Y-%m-%d %H:%M:%S.%f")
    return calendar.timegm(d.timetuple()) + d.microsecond / 1e6
warm = [l for l in open(run + "/node.log", errors="replace") if "Index warm-up" in l]
s0 = samples[0]
off = int(s0["mono_ns"]) - float(s0["unix_s"]) * 1e9
warm_from = warm_to = None
if warm:
    warm_from = log_unix(warm[0]) * 1e9 + off - 1e9
    ends = [l for l in warm if "Index warm-up: read the" in l or "stopped" in l or "failed" in l]
    warm_to = (log_unix(ends[0]) * 1e9 + off + 1e9) if ends else float("inf")
warm_tid, cand = None, Counter()
if warm_from is not None:
    for line in open(run + "/bio.txt"):
        f = line.split()
        # not the main thread: its startup reads (the blocks table) fall in the same interval when the warm-up is short
        if len(f) == 6 and int(f[1]) == pid and int(f[2]) != pid and "R" in f[3] and warm_from <= int(f[0]) <= warm_to:
            cand[int(f[2])] += 1
    if cand:
        warm_tid = cand.most_common(1)[0][0]
warm_reads = Counter()

req = defaultdict(Counter)    # window -> label -> read requests (by the label of their first page)
pages = defaultdict(Counter)  # window -> label -> pages read
wsec = Counter()              # window -> sectors written (any pid)
other_pid_reads = Counter()
thread_reads = Counter()      # tid -> read requests by the node (6-field traces only)
for line in open(run + "/bio.txt"):
    f = line.split()
    if len(f) == 5:
        ns, p, tid, rwbs, sector, nr = int(f[0]), int(f[1]), -1, f[2], int(f[3]), int(f[4])
    elif len(f) == 6:
        ns, p, tid, rwbs, sector, nr = int(f[0]), int(f[1]), int(f[2]), f[3], int(f[4]), int(f[5])
    else:
        continue
    if ns < mono0:
        continue
    w = window_at(ns)
    if "W" in rwbs:
        wsec[w] += nr
        continue
    if "R" not in rwbs:
        continue
    if p != pid:
        other_pid_reads[w] += 1
        continue
    thread_reads[tid] += 1
    if warm_tid is not None and tid == warm_tid:
        first = page_of_sector(sector)
        warm_reads[label_page(first) if first is not None else "(not data.mdb)"] += 1
        continue
    first = page_of_sector(sector)
    if first is None:
        req[w]["(not data.mdb)"] += 1
        pages[w]["(not data.mdb)"] += (nr + 7) // 8
        continue
    req[w][label_page(first)] += 1
    for k in range((nr + 7) // 8):
        pages[w][label_page(first + k)] += 1

# per window: blocks, seconds, CPU
def window_bounds():
    out = {}
    for ns, h, ticks, bio in cpu:
        if h is None:
            continue
        w = max(-1, (h - 1 - START) // W) if h - 1 > START else -1
        o = out.setdefault(w, [ns, ns, h, h, ticks, ticks, bio, bio])
        o[1], o[3], o[5], o[7] = ns, h, ticks, bio
    return out

wb = window_bounds()
keys = ["spent_keys", "tx_indices", "block_heights"]
print("run %s, node pid %d, window %d blocks; reads are the node's own bios on dm-0" % (run, pid, W))
print("win  blocks  wall_s  blk/s  cpu_s/blk  bio_s/blk  reads/blk  spent_keys tx_indices block_heights  other(top)                  new:*  write_MB/blk")
tot_req, tot_pages, tot_blocks = Counter(), Counter(), 0
startup = req.pop(-1, Counter()); pages.pop(-1, None)
for w in sorted(w for w in set(wb) | set(req) if w >= 0):
    b = wb.get(w)
    blocks = (b[3] - b[2]) if b else 0
    wall = (b[1] - b[0]) / 1e9 if b else 0
    cpu_s = (b[5] - b[4]) / 100.0 if b else 0
    bio_s = (b[7] - b[6]) / 100.0 if b else 0
    r = req[w]
    n = sum(r.values())
    tot_req.update(r); tot_pages.update(pages[w]); tot_blocks += max(blocks, 0)
    oth = Counter({k: v for k, v in r.items() if k not in keys and not k.startswith("new:")})
    newn = sum(v for k, v in r.items() if k.startswith("new:"))
    top = ", ".join("%s %d" % kv for kv in oth.most_common(2))
    per = (lambda x: x / blocks) if blocks > 0 else (lambda x: float("nan"))
    print("%3d  %6d  %6.0f  %5.2f  %9.3f  %9.3f  %9.1f  %10.1f %10.1f %13.1f  %-26s %6.1f  %8.2f" % (
        w, blocks, wall, blocks / wall if wall else 0, per(cpu_s), per(bio_s), per(n), per(r["spent_keys"]), per(r["tx_indices"]),
        per(r["block_heights"]), top[:26], per(newn), per(wsec[w] * 512 / 1e6)))
print("startup, before the first block (not counted below): %d read requests; top: %s" % (sum(startup.values()), ", ".join("%s %d" % kv for kv in startup.most_common(4))))
print("the warm-up thread (tid %s), not counted below: %d read requests; %s" % (warm_tid, sum(warm_reads.values()), ", ".join("%s %d" % kv for kv in warm_reads.most_common(4))))
print("totals over %d blocks (windows 0 and up, warm-up thread excluded): read requests %d, pages %d; by label (requests):" % (tot_blocks, sum(tot_req.values()), sum(tot_pages.values())))
for k, v in tot_req.most_common():
    print("  %-28s %9d  %6.2f per block" % (k, v, v / tot_blocks if tot_blocks else 0))
print("reads by other pids (source node, kworkers): %d" % sum(other_pid_reads.values()))
if any(t != -1 for t in thread_reads):
    print("the node's read requests by thread id (top 12):")
    for t, v in thread_reads.most_common(12):
        print("  tid %-8d %9d" % (t, v))
